export interface NodeRuntimeMetrics {
    cpu: {
        user: number;
        system: number;
        percentageUsed: number;
    };
    memory: {
        rss: number;
        heapTotal: number;
        heapUsed: number;
        external: number;
        arrayBuffers?: number;
        percentageUsed: number;
    };
    gc: {
        count: number;
        totalDuration: number;
        /**
         * Per-kind counts for the window. Every member is optional because the
         * section is reported on every sample, and a window in which nothing was
         * collected reports it empty rather than omitting it.
         */
        breakdown?: {
            minor?: {
                count: number;
                duration: number;
            };
            major?: {
                count: number;
                duration: number;
            };
            incremental?: {
                count: number;
                duration: number;
            };
        };
    };
    eventLoop: {
        lag: number;
        utilization: number;
    };
}
